String makePalindrome(String stringArg0) {
  final List<String> chars = stringArg0.split('');
  int leftIndex = 0;
  int rightIndex = chars.length - 1;

  while (leftIndex < rightIndex) {
    if (chars[leftIndex] != chars[rightIndex]) {
      // Find the next matching character from the left or right side
      bool foundMatchFromLeft = false;
      bool foundMatchFromRight = false;
      String? matchChar;

      for (int i = leftIndex + 1; i <= rightIndex && !foundMatchFromLeft; i++) {
        if (chars[i] == chars[rightIndex]) {
          foundMatchFromLeft = true;
          matchChar = chars[i];
        }
      }

      for (int j = rightIndex - 1; j >= leftIndex && !foundMatchFromRight; j--) {
        if (chars[j] == chars[leftIndex]) {
          foundMatchFromRight = true;
          matchChar = chars[j];
        }
      }

      if (!foundMatchFromLeft && !foundMatchFromRight) {
        return '';
      } else if (foundMatchFromLeft && !foundMatchFromRight) {
        chars[rightIndex] = matchChar!;
      } else if (!foundMatchFromLeft && foundMatchFromRight) {
        chars[leftIndex] = matchChar!;
      } else {
        // Both sides have a match, choose one arbitrarily (e.g., left)
        chars[rightIndex] = matchChar!;
      }
    }

    leftIndex++;
    rightIndex--;
  }

  return chars.join('');
