  double max = numbers.reduce(max);

  if (min == max) {
    // All elements are the same, so scale to [0.0, 1.0]
    List<double> result = [];
    for (var _ in numbers) {
      result.add(0.0);
    }
    result[0] = 1.0;
    return result;
