  final Set<String> set2 = Set.from(lst2);

  final Map<String, int> countMap = <String, int>{};

  for (final String item in [...set1, ...set2]) {
    if (!countMap.containsKey(item)) {
      countMap[item] = 0;
    }
    countMap[item] = countMap[item]! + 1;
  }

