  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  final visited = List.generate(rows, (_) => List.filled(cols, false));

  var result = 0;
  for (var i = 0; i < rows; ++i) {
    for (var j = 0; j < cols; ++j) {
      if (!visited[i][j]) {
        // Start DFS
        final area = dfs(grid, visited, i, j, capacity);
        result += area;
      }
    }
  }

  return result;
}

int dfs(List<List<int>> grid, List<List<bool>> visited, int r, int c, int capacity) {
  final rows = grid.length;
  final cols = grid[0].length;

  if (r < 0 || r >= rows || c < 0 || c >= cols || visited[r][c] || grid[r][c] != 1) {
    return 0;
  }

  visited[r][c] = true;
  int count = 1;

  // Directions: up, down, left, right
  const directions = [(-1, 0), (1, 0), (0, -1), (0, 1)];

  for (final dir in directions) {
    final nr = r + dir[0];
    final nc = c + dir[1];
    count += dfs(grid, visited, nr, nc, capacity);
  }

  return count;
}

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Create a 2D array to store the maximum fill at each cell
  var dp = List.generate(rows, (_) => List.filled(cols, 0));

  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      if (i == 0 || j == 0) {
        // First row or first column: can only take from one direction
        dp[i][j] = grid[i][j];
      } else {
        // Take the minimum of three possible directions and add current value
        dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + grid[i][j];
      }
    }
  }

  // Find the maximum value in the last row or last column
  int result = 0;
  for (final val in dp.last) {
    result = max(result, val);
  }
  return result;
}

