int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Calculate the maximum number of layers possible
  var maxLayers = 0;
  for (var i = 0; i < rows; i++) {
    maxLayers += grid[i][cols - 1];
  }

  // Binary search between 1 and maxLayers to find the minimum valid k
  int low = 1;
  int high = maxLayers;
  while (low < high) {
    final mid = (low + high + 1) ~/ 2;
    if (_canFit(grid, capacity, mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }

  return low;
}

bool _canFit(List<List<int>> grid, int capacity, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  for (var col = 0; col < cols; col++) {
    int total = 0;

    for (var row = 0; row < rows; row++) {
      total += grid[row][col];

      // If we've filled up this column enough times, subtract it from the count
      if (total >= k) {
        total -= grid[row][col]; 
        break;
      }
    }

    // Check that even after subtracting, we have at least one layer left in each column
    if (total < k) {
      return false;
    }
  }

  return true;
}

