  int totalWaterCells = 0;

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (grid[i][j] != -1) { 
        totalWaterCells++;
      }
    }
  }

  // Check how many columns we need to fill from each side.
  int leftColToFill = 0;
  int rightColToFill = cols - 1;
  while (leftColToFill <= rightColToFill && grid[leftColToFill][cols-1] == -1) {
    leftColToFill++;
  }
  while (rightColToFill >= leftColToFill && grid[rightColToFill][0] == -1) {
    rightColToFill--;
  }

  // If no column is available to fill, all cells are already filled. Return min between total and capacity.
  if (leftColToFill > rightColToFill) {
    return min(totalWaterCells, capacity);
  }

  // The maximum possible fill would be based on filling from both sides towards center.
  int colCountFromLeft = leftColToFill + 1;
  int colCountFromRight = cols - rightColToFill - 1;
  int maxPossible = colCountFromLeft * colCountFromRight;

  // Determine which direction gives more coverage, but not exceeding capacity.
  int actualMax = 0;
  if (colCountFromLeft <= colCountFromRight) {
    actualMax += colCountFromLeft * colCountFromRight;
  } else {
    actualMax += colCountFromLeft * colCountFromRight;
  }

  // Ensure it doesn't exceed capacity or the total possible.
  return min(actualMax, capacity);
}
