String getClosestVowel(String word) {
  final vowels = ['a', 'e', 'i', 'o', 'u'];

  // Helper to check if a character is a vowel
  bool isVowel(char) => vowels.contains(char.toLowerCase());

  for (int i = 0; i < word.length; i++) {
    var currentChar = word[i];

    // Check if the current character is a vowel
    if (isVowel(currentChar)) {
      return currentChar;
    }

    // Find the closest vowel before and after
    int? prevIndex, nextIndex;
    for (int j = i - 1; j >= 0 && prevIndex == null; j--) {
      if (isVowel(word[j])) {
        prevIndex = j;
      }
    }
    for (int j = i + 1; j < word.length && nextIndex == null; j++) {
      if (isVowel(word[j])) {
        nextIndex = j;
      }
    }

    // If both are found, pick closer one
    if (prevIndex != null && nextIndex != null) {
      if ((i - prevIndex) <= (nextIndex - i)) {
        return word[prevIndex];
      } else {
        return word[nextIndex];
      }
    }

    // If only one of them exists, pick that one
    if (prevIndex != null) {
      return word[prevIndex];
    }
    if (nextIndex != null) {
      return word[nextIndex];
    }
  }

  // No vowels found in the word
  return '';
}

