// Helper function to check if a string has balanced parentheses.
bool isBalancedParentheses(String s) {
  int balance = 0;
  for (final char in s.split('')) {
    if (char == '(') {
      balance++;
    } else if (char == ')') {
      balance--;
      if (balance < 0) {
        // If at any point the closing parenthesis exceeds opening, it's unbalanced.
        return false;
      }
    }
  }
  return balance == 0;
}

