  Map<int, int> openIndices = {};
  Map<int, int> closeIndices = {};

  int currentDepth = 0;

  for (int i = 0; i < string.length; i++) {
    if (string[i] == '(') {
      openIndices[currentDepth] = i;
      currentDepth++;
    } else if (string[i] == ')') {
