        }
    }

    if (!isValidBaseName) break;
  }

  if (!isValidBaseName) return 'Invalid file name: invalid characters in base name';

  // Validate extension
  bool isValidExt = true;
  for (var ch in extPart.characters) {
    if (!ch.isLetterOrDigit && ch != '_' && ch != '-') {
      isValidExt = false;
      break;
    }
  }

