  if (operator.isEmpty || operand.length != operator.length + 1) throw ArgumentError();

  var result = operand[0];
  for (int i = 0; i < operator.length; ++i) {
    switch (operator[i]) {
      case '+':
        result += operand[i + 1];
        break;
      case '-':
        result -= operand[i + 1];
        break;
      case '*':
        result *= operand[i + 1];
        break;
      case '/':
        if (operand[i + 1] == 0) throw ArgumentError();
        result /= operand[i + 1];
        break;
      default:
        throw ArgumentError();
    }
  }

  return result;
}

