  if (n < 2) return s;

  int left = 0, right = n - 1;
  bool isPalindrome = true;
  List<String> palindromeChars = [];

  while (left < right) {
    // Skip spaces on the left
    while (s[left] == ' ') left++;
    // Skip spaces on the right
    while (s[right] == ' ') right--;

    if (s[left] != s[right]) {
      isPalindrome = false;
      break;
    }

    palindromeChars.add(s[left]);
    left++;
    right--;
  }

  // If it's a palindrome, just return the original string trimmed of extra spaces
  if (isPalindrome && palindromeChars.isNotEmpty) {
    return s.trim();
  }

  // Build the new string by reversing the palindromic part and appending remaining characters
  String reversedPalin = reverseString(palindromeChars.join(''));
  String restOfStr = s.substring(palindromeChars.length);

  return reversedPalin + restOfStr;
}
